WITH valid AS (SELECT id, session_id, event_type, page, event_time, duration_sec, CEIL(duration_sec) AS duration_sec_whole, CONCAT_WS(',', page, event_type) AS page_event_type_key, COALESCE(page, 'DIRECT') AS resolved_page FROM web_events WHERE event_time > TIMESTAMP '2023-07-26 06:00:00' AND page IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, BIT_OR(duration_sec) AS duration_sec_bit_or, COUNT(CASE WHEN event_type = 'page_view' THEN 1 END) AS page_view_count, COUNT_IF(event_type = 'search') AS search_events, COUNT(*) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_rows, MIN(event_time) AS first_seen, MAX(is_new_session) FILTER (WHERE page = '/checkout') AS checkout_max_is_new_session FROM islands GROUP BY 1;
